const items = $input.all();
const raw = items[0].json[0]?.text ?? items[0].json?.text;

// Retire les backticks markdown (avec ou sans "json")
const jsonString = raw
  .replace(/^```[a-z]*\n?/i, '')  // retire ```json ou ``` au début
  .replace(/```\s*$/, '')          // retire ``` à la fin
  .trim();

const parsed = JSON.parse(jsonString);

return {
  json : {
    message : parsed.message,
    sell : parsed.sell.message_for_marketing
  }
}
